# owner: platform
"""Lay students out in seating rows."""

from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def sort_key(student: Student) -> tuple:
    return (student.last_name, student.first_name)


def seating_rows(
    students: List[Student], per_row: int
) -> List[str]:
    if per_row <= 0 or not students:
        raise ProjectError("need students and seats")
    names = [
        stud.display_name
        for stud in sorted(students, key=sort_key)
    ]
    return [
        f"Row {start // per_row + 1}: "
        + " | ".join(names[start:start + per_row])
        for start in range(0, len(names), per_row)
    ]

