# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def make_student(last: str, first: str) -> Student:
    return Student("1", last, first, "A")


class SeatingRowsTests(unittest.TestCase):
    def test_sorted_and_chunked(self):
        studs = [
            make_student("Halloway", "Juno"),
            make_student("Dunmere", "Piet"),
            make_student("Adler", "Zoya")
        ]
        self.assertEqual(
            seating_rows(studs, 2),
            [
                "Row 1: Adler, Zoya | Dunmere, Piet",
                "Row 2: Halloway, Juno"
            ]
        )

    def test_bad_seat_count(self):
        studs = [make_student("Adler", "Zoya")]
        for seats in (0, -1):
            with self.assertRaises(ProjectError):
                seating_rows(studs, seats)

    def test_no_students(self):
        with self.assertRaises(ProjectError):
            seating_rows([], 3)
